/** Public entry point — the only module consumers/docs should import from. */

export { DataGridKeybindingsDialog, type DataGridKeybindingsDialogProps } from "./keybindings-dialog";
export {
  useDataGridKeybindings,
  type UseDataGridKeybindingsOptions,
  type UseDataGridKeybindingsResult,
} from "./use-data-grid-keybindings";
export { BindingChips } from "./binding-label";

// Relative on purpose: the shadcn CLI rewrites import paths, never augmentation module names.
declare module "../data-grid/types" {
  interface GridActions {
    openKeybindings: true;
  }
}

"use client";

import { cn } from "@/lib/utils";
import { useMemo, type ReactElement, type ReactNode } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogTrigger,
} from "@/components/ui/dialog";
import { useDataGridKeymap, useDataGridLabels, type DataGridLabels, type GridAction, type GridCommand, type Keymap } from "@/registry/default/components/data-grid/data-grid";
import { KEYBINDING_CATEGORIES, categoryForAction, categoryLabel, type KeybindingCategory } from "./action-groups";
import { labelForAction } from "./action-labels";
import { BindingChips } from "./binding-label";
import { useDataGridCommands, useDataGridSelector } from "@/registry/default/components/data-grid/data-grid-sdk";

const INSERT_ROW_ACTIONS: ReadonlySet<string> = new Set(["insertRowAbove", "insertRowBelow"]);

type WiredRowFactories = { createRow: boolean; duplicateRow: boolean };

function isWired(action: string, commands: Record<string, GridCommand> | null, factories: WiredRowFactories): boolean {
  if (commands?.[action]) return true;
  if (INSERT_ROW_ACTIONS.has(action)) return factories.createRow;
  return action !== "duplicateRow" || factories.duplicateRow;
}

/** One always-on native clipboard shortcut not covered by the keymap (copy/cut/paste are native browser events, see use-grid-clipboard.ts); labels come from `labels.keybindings.native*` (i18n). */
function nativeClipboardBindings(labels: DataGridLabels): { label: string; binding: string }[] {
  return [
    { label: labels.keybindings.nativeCopy, binding: "mod+c" },
    { label: labels.keybindings.nativeCut, binding: "mod+x" },
    { label: labels.keybindings.nativePaste, binding: "mod+v" },
  ];
}

/** A dialog row: either a keymap-driven `GridAction` (key = action name) or a native binding (key = its label). */
type KeymapRow = { key: string; label: string; bindings: string[] };

/** Every bound action in `keymap` plus the native clipboard bindings, grouped by category in {@link KEYBINDING_CATEGORIES} order; categories with no rows are omitted. Custom commands (`commands`) override a row's label and category. */
function groupKeymap(keymap: Keymap, labels: DataGridLabels, commands: Record<string, GridCommand> | null, factories: WiredRowFactories): { category: KeybindingCategory; rows: KeymapRow[] }[] {
  const byCategory = new Map<KeybindingCategory, KeymapRow[]>();
  const pushRow = (category: KeybindingCategory, row: KeymapRow) => {
    const list = byCategory.get(category) ?? [];
    list.push(row);
    byCategory.set(category, list);
  };

  for (const [action, bindings] of Object.entries(keymap) as [GridAction, string[] | undefined][]) {
    if (!bindings || bindings.length === 0 || !isWired(action, commands, factories)) continue;
    const command = commands?.[action];
    pushRow(command?.group ?? categoryForAction(action), {
      key: action,
      label: command?.label ?? labelForAction(action, labels),
      bindings,
    });
  }
  // native clipboard events (copy/cut/paste) aren't GridActions/keymap entries — see use-grid-clipboard.ts
  for (const { label, binding } of nativeClipboardBindings(labels)) {
    pushRow("clipboardFill", { key: label, label, bindings: [binding] });
  }

  return KEYBINDING_CATEGORIES.map((category) => ({ category, rows: byCategory.get(category) ?? [] })).filter(
    (group) => group.rows.length > 0,
  );
}

/** Props for {@link DataGridKeybindingsDialog}. */
export type DataGridKeybindingsDialogProps = {
  /** Controlled open state; omit for uncontrolled (internal) state. */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Uncontrolled initial open state; ignored when `open` is provided. */
  defaultOpen?: boolean;
  /** Rendered as the dialog's trigger (e.g. a `<Button>`); omit to drive `open` externally only. */
  trigger?: ReactElement;
  /** Merged into the dialog content root. */
  className?: string;
};

/**
 * Lists every bound `GridAction` that does something on the mounted grid, from its EFFECTIVE keymap (`DEFAULT_KEYMAP` merged
 * with the plugins' keymaps, then the `keymap` prop, via `useDataGridKeymap`) — never a hardcoded shortcut list, so
 * consumer overrides/extensions show up automatically. Grouped by category, platform-aware `<kbd>`
 * chips (⌘ on mac, Ctrl elsewhere; Space/arrow glyphs). Copy/Cut/Paste are appended separately since
 * they're native browser clipboard events, not part of the keymap.
 */
export function DataGridKeybindingsDialog(props: DataGridKeybindingsDialogProps): ReactNode {
  const { open, onOpenChange, defaultOpen, trigger, className } = props;
  const keymap = useDataGridKeymap();
  const labels = useDataGridLabels();
  const commands = useDataGridCommands();
  const createRow = useDataGridSelector((s) => s.createRow != null);
  const duplicateRow = useDataGridSelector((s) => s.duplicateRow != null);
  const groups = useMemo(() => groupKeymap(keymap, labels, commands, { createRow, duplicateRow }), [keymap, labels, commands, createRow, duplicateRow]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange} defaultOpen={defaultOpen}>
      {trigger && <DialogTrigger render={trigger} />}
      <DialogContent className={cn("max-h-[80vh] max-w-lg overflow-y-auto sm:max-w-lg", className)} data-slot="data-grid-keybindings-dialog">
        <DialogHeader>
          <DialogTitle>{labels.keybindings.title}</DialogTitle>
          <DialogDescription>{labels.keybindings.description}</DialogDescription>
        </DialogHeader>
        <div className="flex flex-col gap-4">
          {groups.map(({ category, rows }) => (
            <section key={category} data-keybindings-category={category}>
              <h3 className="mb-1.5 text-xs font-semibold tracking-wide text-muted-foreground uppercase">{categoryLabel(category, labels)}</h3>
              <ul className="flex flex-col gap-1">
                {rows.map((row) => (
                  <li key={row.key} data-keybindings-action={row.key} className="flex items-center justify-between gap-4 py-0.5">
                    <span className="text-foreground">{row.label}</span>
                    <div className="flex items-center gap-2">
                      {row.bindings.map((binding) => (
                        <BindingChips key={binding} binding={binding} />
                      ))}
                    </div>
                  </li>
                ))}
              </ul>
            </section>
          ))}
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useMemo, useState, useSyncExternalStore, type ComponentType } from "react";
import type { DataGridPlugin } from "@/registry/default/components/data-grid/data-grid";
import { DataGridKeybindingsDialog } from "./keybindings-dialog";

export type UseDataGridKeybindingsOptions = {
  /** Merged into the root of the dialog. */
  className?: string;
};

export type UseDataGridKeybindingsResult = {
  /** One entry of the grid's `plugins`: the dialog, the `openKeybindings` command, and its `?` binding. */
  plugin: DataGridPlugin<unknown>;
  open: () => void;
  close: () => void;
};

type OpenStore = {
  get: () => boolean;
  set: (open: boolean) => void;
  subscribe: (listener: () => void) => () => void;
};

function createOpenStore(): OpenStore {
  const listeners = new Set<() => void>();
  let isOpen = false;
  return {
    get: () => isOpen,
    set(next) {
      if (next === isOpen) return;
      isOpen = next;
      listeners.forEach((listener) => listener());
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

function KeybindingsMount({ store, className }: { store: OpenStore; className?: string }) {
  const open = useSyncExternalStore(store.subscribe, store.get, store.get);
  return <DataGridKeybindingsDialog open={open} onOpenChange={store.set} className={className} />;
}

/**
 * A dialog that lists the grid's effective keymap. Pass `plugin` in the grid's `plugins`; `?`
 * opens the dialog, and `keymap={{ openKeybindings: [...] }}` rebinds or (with `[]`) removes the key.
 */
export function useDataGridKeybindings(options: UseDataGridKeybindingsOptions = {}): UseDataGridKeybindingsResult {
  const [store] = useState(createOpenStore);
  const { className } = options;

  const plugin = useMemo<DataGridPlugin<unknown>>(() => {
    const Mount: ComponentType = () => <KeybindingsMount store={store} className={className} />;
    return {
      name: "keybindings",
      Mount,
      commands: { openKeybindings: { run: () => store.set(true), group: "other" } },
      keymap: { openKeybindings: ["?"] },
    };
  }, [store, className]);

  return useMemo(() => ({ plugin, open: () => store.set(true), close: () => store.set(false) }), [plugin, store]);
}

"use client";

import type { ReactNode } from "react";
import { useShortcutLabel } from "@/registry/default/components/data-grid/data-grid";
import { Kbd, KbdGroup } from "@/components/ui/kbd";

/** One binding string ("mod+c") rendered as a row of `<Kbd>` chips ("⌘" "C"). */
export function BindingChips({ binding, className }: { binding: string; className?: string }): ReactNode {
  const tokens = useShortcutLabel(binding);
  return (
    <KbdGroup className={className}>
      {tokens.map((token, i) => (
        // tokens within one binding have no other stable identity; index is fine, this list never reorders
        <Kbd key={i}>{token}</Kbd>
      ))}
    </KbdGroup>
  );
}

import type { DataGridLabels, GridAction } from "@/registry/default/components/data-grid/data-grid";

/** Splits "camelCaseAction" into "Camel case action" for actions missing from {@link DataGridLabels.keybindings.actions}. */
function humanizeActionName(action: string): string {
  const spaced = action.replace(/([a-z0-9])([A-Z])/g, "$1 $2").toLowerCase();
  return spaced.charAt(0).toUpperCase() + spaced.slice(1);
}

/** Human label for `action` from {@link DataGridLabels.keybindings.actions}, falling back to a humanized form of its name for consumer-added actions. */
export function labelForAction(action: GridAction, labels: DataGridLabels): string {
  return labels.keybindings.actions[action] ?? humanizeActionName(action);
}

import { cn } from "@/lib/utils"

/** Keycap treatment, owned by the component (not the prose typography plugin) so docs, the keybindings dialog, and consumer apps render identically. */
const KEYCAP =
  "rounded-sm border bg-muted shadow-[inset_0_-2px_0_0_color-mix(in_oklab,_currentColor_15%,_transparent)]"

function Kbd({ className, ...props }: React.ComponentProps<"kbd">) {
  return (
    <kbd
      data-slot="kbd"
      className={cn(
        // `not-prose`: the typography plugin's kbd rule (unlayered) would otherwise restyle component-owned keys
        "pointer-events-none not-prose inline-flex h-5 w-fit min-w-5 select-none items-center justify-center gap-1 px-1 font-sans text-xs font-medium text-muted-foreground",
        KEYCAP,
        "in-data-[slot=kbd-group]:min-w-0 in-data-[slot=kbd-group]:border-0 in-data-[slot=kbd-group]:bg-transparent in-data-[slot=kbd-group]:px-0.5 in-data-[slot=kbd-group]:shadow-none",
        "in-data-[slot=tooltip-content]:bg-background/20 in-data-[slot=tooltip-content]:text-background dark:in-data-[slot=tooltip-content]:bg-background/10",
        "[&_svg:not([class*='size-'])]:size-3",
        className
      )}
      {...props}
    />
  )
}

/** One keycap for a whole binding; inner `Kbd` chips flatten via `in-data-[slot=kbd-group]` and stay separated by the gap. */
function KbdGroup({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="kbd-group"
      className={cn(
        "pointer-events-none inline-flex h-5 select-none items-center gap-1 px-1 font-sans text-xs font-medium text-muted-foreground",
        KEYCAP,
        className
      )}
      {...props}
    />
  )
}

export { Kbd, KbdGroup }
